{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The proportion of people who will remain asymptomatic throughout the course of infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the cause of coronavirus disease 2019 (COVID-19), is not known. Studies that assess people at just one time point will overestimate the proportion of true asymptomatic infection because those who go on to develop COVID-19 symptoms will be wrongly classified as asymptomatic rather than presymptomatic.",
      "reason": "The manuscript explicitly states the current uncertainty about the proportion truly asymptomatic and explains an important uncertainty (misclassification due to single time-point assessment)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The amount, and infectiousness, of asymptomatic SARS-CoV-2 infection will determine what kind of measures will prevent transmission most effectively.",
      "reason": "The authors state why the question matters for public health (importance of understanding asymptomatic infection to inform preventive measures) and justify the need for the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "Wefound narrative reviews that reported wide ranges (5%-96%) of infections that might be asymptomatic [1,118]. ... We found three systematic reviews, which reported similar summary estimates from meta-analysis of studies published up to May [119-121]. ... Our review includes all these studies, mostly in the categories of aggregated contact or outbreak investigations, with compatible summary estimates (Fig 1). ... In comparison with other reviews, rather than restricting inclusion, we give a comprehensive overview of studies with adequate follow-up, with assessment of risks of bias and exploration of heterogeneity (S2-S7 Figs).",
      "reason": "The manuscript identifies existing systematic reviews, compares findings, cites them, and explains how the current review differs and why it is needed (comprehensive overview with assessment of follow-up, bias, and heterogeneity)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses proportions of asymptomatic and presymptomatic SARS-CoV-2 infection and transmission, not effects of interventions; thus a mechanism-of-action description for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context, so inclusion of a logic model depicting intervention components and outcomes is not applicable."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We conducted a living systematic review and metaanalysis to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion does not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The manuscript explicitly states three review questions/objectives, framed as clear questions addressing proportions and transmission, satisfying the requirement for explicit objectives/questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "The objectives of this study were to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion do not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The review addresses descriptive questions about proportions and transmission, not intervention effects; therefore planned comparisons using PICO are not applicable."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Weincluded studies in any language of people with SARS-CoV-2 diagnosed by RT-PCR that documented follow-up and symptom status at the beginning and end of follow-up or investigated the contribution to SARS-CoV-2 transmission of asymptomatic or presymptomatic infection. We included contact-tracing investigations, case series, cohort studies, case-control studies, and statistical and mathematical modelling studies. We excluded the following study types: case reports of a single patient and case series in which participants were not enrolled consecutively. When multiple records included data from the same study population, we linked the records and extracted data from the most complete report.",
      "reason": "Specifies key study characteristics for eligibility: diagnostic method (RT-PCR), requirement for documented follow-up and symptom status, included study designs, and excluded study types; also addresses duplicate records."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Weincluded studies in any language of people with SARS-CoV-2 diagnosed by RT-PCR that documented follow-up and symptom status at the beginning and end of follow-up or investigated the contribution to SARS-CoV-2 transmission of asymptomatic or presymptomatic infection.",
      "reason": "Reports inclusion irrespective of language (explicit). However, the manuscript does not explicitly specify other report-characteristic criteria such as dissemination year or formal publication/report status (beyond later noting some included records were preprints), so reporting of all report-characteristic eligibility criteria is incomplete."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured versus exclusion because outcome results were not reported was found in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "We used the 'metaprop' and 'metabin' functions from the 'meta' package (version 4.11-0) [14] in R (version 3.5.1) to display the study findings in forest plots and synthesise their findings. ... We examined heterogeneity visually in forest plots. We stratified studies according to the methods used to identify people with asymptomatic SARS-CoV-2 infection and the study setting. To synthesise proportions from comparable studies, in terms of design and population, we used stratified random-effects meta-analysis. For the stratified and overall summary estimates, we calculated prediction intervals, to represent the likely range of proportions that would be obtained in subsequent studies conducted in similar settings [16]. ... We compared the secondary attack rate from asymptomatic or presymptomatic index cases with that from symptomatic cases.",
      "reason": "Specifies how studies were grouped for syntheses (stratified by methods to identify asymptomatic infection and by study setting), and links groupings to the comparisons/summaries (proportions and secondary attack rate comparisons)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "In comparison with other reviews, rather than restricting inclusion, we give a comprehensive overview of studies with adequate follow-up, with assessment of risks of bias and exploration of heterogeneity (S2-S7 Figs).",
      "reason": "Provides some rationale regarding restricting to studies with adequate follow-up (to assess outcomes and reduce bias) and contrasts approach with other reviews, but does not comprehensively justify all notable eligibility restrictions (e.g., exclusion of single case reports or non-consecutive case series) in the supplied text."
    }
  ],
  "confidence": 85
}

